  // Privacy modal
  'privacy.title': 'Privacybeleid',
  'privacy.subtitle': 'Hoe we jouw gegevens beschermen en verwerken',
  'privacy.lastUpdated': 'Laatst bijgewerkt: maart 2026',
  'privacy.dataCollection.title': 'Gegevensverzameling',
  'privacy.dataCollection.body': 'We verzamelen alleen de informatie die nodig is om onze e-mailservice te bieden: je naam, e-mailadres en de inhoud van berichten die je verzendt en ontvangt. We verkopen of delen je persoonlijke gegevens niet met derden voor marketingdoeleinden.',
  'privacy.dataUsage.title': 'Hoe We Jouw Gegevens Gebruiken',
  'privacy.dataUsage.body': 'Jouw gegevens worden uitsluitend gebruikt om de e-mailservice te beheren en te verbeteren, inclusief het afleveren van berichten, het filteren van spam, het bieden van AI-gestuurde functies (met jouw toestemming) en het handhaven van de beveiliging van je account.',
  'privacy.dataSecurity.title': 'Gegevensbeveiliging',
  'privacy.dataSecurity.body': 'We gebruiken industriestandaard encryptie (TLS/SSL) voor alle gegevens in transit en in rust. Sessies zijn beschermd met versleutelde tokens en CSRF-bescherming. We controleren regelmatig onze beveiligingspraktijken.',
  'privacy.cookies.title': 'Cookies & Lokale Opslag',
  'privacy.cookies.body': 'We gebruiken essentiële cookies en lokale opslag om je sessie te behouden, je voorkeuren (thema, taal) te onthouden en een naadloze ervaring te bieden. We gebruiken geen trackingcookies van derden.',
  'privacy.thirdParties.title': 'Diensten van Derden',
  'privacy.thirdParties.body': 'We kunnen diensten van derden gebruiken voor specifieke functionaliteit zoals AI-functies (Anthropic Claude) en pushmeldingen. Deze diensten zijn gebonden aan hun eigen privacybeleid en verwerken alleen de minimale gegevens die nodig zijn.',
  'privacy.rights.title': 'Jouw Rechten',
  'privacy.rights.body': 'Je hebt het recht om je persoonlijke gegevens op elk moment in te zien, te corrigeren, te exporteren of te verwijderen. Je kunt je gegevens beheren via Instellingen of door contact op te nemen met ons ondersteuningsteam.',
  'privacy.contact.title': 'Neem Contact Met Ons Op',
  'privacy.contact.body': 'Voor vragen over privacy of gegevensverzoeken, neem contact met ons op via privacy@chatyy.app. We reageren binnen 30 dagen.',

