  'terms.title': 'Servicevoorwaarden',
  'terms.subtitle': 'Richtlijnen voor het gebruik van Chatyy',
  'terms.lastUpdated': 'Laatst bijgewerkt: maart 2026',
  'terms.acceptance.title': 'Acceptatie van Voorwaarden',
  'terms.acceptance.body': 'Door toegang te krijgen tot of gebruik te maken van Chatyy, ga je akkoord met deze Servicevoorwaarden. Als je het niet eens bent met een deel van deze voorwaarden, mag je de service niet gebruiken.',
  'terms.services.title': 'Beschrijving van Diensten',
  'terms.services.body': 'Chatyy biedt e-mailcommunicatiediensten, waaronder het verzenden, ontvangen en beheren van e-mails, samen met AI-gestuurde functies, kalenderintegratie en videoconferentiemogelijkheden.',
  'terms.accounts.title': 'Gebruikersaccounts',
  'terms.accounts.body': 'Je bent verantwoordelijk voor het behouden van de beveiliging van je accountgegevens. Je mag je wachtwoord niet delen of ongeautoriseerde toegang tot je account toestaan. Je moet minimaal 13 jaar oud zijn om deze service te gebruiken.',
  'terms.conduct.title': 'Acceptabel Gebruik',
  'terms.conduct.body': 'Je gaat ermee akkoord de service niet te gebruiken voor het verzenden van spam, malware, phishing of enige illegale inhoud. Je mag niet proberen toegang te krijgen tot de accounts van andere gebruikers of de service-infrastructuur te verstoren.',
  'terms.content.title': 'Inhoudseigendom',
  'terms.content.body': 'Je behoudt het eigendom van alle inhoud die je creëert en verzendt via de service. We claimen geen eigendom over je e-mails of bijlagen. We kunnen inhoud verwerken zoals nodig is om de service te bieden.',
  'terms.limitation.title': 'Beperking van Aansprakelijkheid',
  'terms.limitation.body': 'Chatyy wordt "zoals het is" aangeboden. We streven naar 99,9% uptime, maar garanderen geen ononderbroken service. We zijn niet aansprakelijk voor enige indirecte, incidentele of gevolgschade die voortvloeit uit jouw gebruik van de service.',
  'terms.termination.title': 'Accountbeëindiging',
  'terms.termination.body': 'We kunnen accounts opschorten of beëindigen die deze voorwaarden schenden. Je kunt je account op elk moment verwijderen via Instellingen. Na beëindiging worden je gegevens binnen 30 dagen verwijderd.',
  'terms.changes.title': 'Wijzigingen in Voorwaarden',
  'terms.changes.body': 'We kunnen deze voorwaarden van tijd tot tijd bijwerken. We zullen je op de hoogte stellen van belangrijke wijzigingen via e-mail of in-app melding. Voortgezet gebruik van de service na wijzigingen betekent acceptatie van de bijgewerkte voorwaarden.',

